// route: 0 card button, 1 message, 2 nothing to do. Lark needs an answer within 3 seconds.
const body = $json.body || {};
if (body.encrypt) return [{ json: { route: 2, response: {} } }];
if (body.type === 'url_verification') return [{ json: { route: 2, response: { challenge: body.challenge } } }];
const header = body.header || {};
const event = body.event || {};
if (header.event_type === 'card.action.trigger') {
  const value = (event.action && event.action.value) || {};
  return [{ json: {
    route: 0, response: { toast: { type: 'info', content: 'Đã nhận' } },
    action: value.a, id: Number(value.id) || 0, token: value.t,
    operator: (event.operator && event.operator.open_id) || '',
    chat_id: (event.context && event.context.open_chat_id) || '',
    message_id: (event.context && event.context.open_message_id) || '',
  } }];
}
if (header.event_type === 'im.message.receive_v1') {
  const m = event.message || {};
  if (!['p2p', 'group'].includes(m.chat_type)) return [{ json: { route: 2, response: {} } }];
  return [{ json: { route: 1, response: {}, message_id: m.message_id, chat_type: m.chat_type } }];
}
return [{ json: { route: 2, response: {} } }];

const TZ = 'Asia/Ho_Chi_Minh';
// The NocoDB node nests a row as { id, id_fields, fields }.
const rowsOf = (name) => ($(name).isExecuted ? $(name).all() : [])
  .map((i) => i.json || {})
  .filter((j) => j.id !== undefined && j.id !== null)
  .map((j) => ({ Id: j.id, ...(j.fields || {}) }));
const settingsOf = (name) => Object.fromEntries(
  rowsOf(name).filter((r) => r.key).map((r) => [r.key, (r.value ?? '').toString().trim()]));
const linesOf = (v) => String(v || '').split('\n').map((s) => s.trim()).filter(Boolean);
// NocoDB returns DateTime in UTC as "2026-09-17 13:00:00+00:00".
const parseDt = (s) => DateTime.fromISO(String(s || '').trim().replace(' ', 'T'), { setZone: true }).setZone(TZ);
const iso = (dt) => dt.setZone(TZ).toISO({ suppressMilliseconds: true });

const DAYS = { mon: 1, tue: 2, wed: 3, thu: 4, fri: 5, sat: 6, sun: 7 };
// slots: lines like "sat-20:00". taken: ISO times already booked. The first free one after `after`.
const nextSlot = (slots, taken, after) => {
  const parsed = linesOf(slots).map((s) => s.toLowerCase().match(/^(mon|tue|wed|thu|fri|sat|sun)-(\d{2}):(\d{2})$/)).filter(Boolean)
    .map((m) => ({ label: m[0], weekday: DAYS[m[1]], hour: Number(m[2]), minute: Number(m[3]) }));
  const booked = new Set(taken.map((t) => parseDt(t).toFormat('yyyy-MM-dd HH:mm')));
  for (let d = 0; d < 60; d++) {
    const day = after.startOf('day').plus({ days: d });
    const today = parsed.filter((s) => s.weekday === day.weekday).sort((a, b) => a.hour * 60 + a.minute - b.hour * 60 - b.minute);
    for (const s of today) {
      const t = day.set({ hour: s.hour, minute: s.minute });
      if (t > after && !booked.has(t.toFormat('yyyy-MM-dd HH:mm'))) return { at: t, slot: s.label };
    }
  }
  return null;
};

const c = $('Classify').first().json;
const s = settingsOf('Settings');
// The owner, or anyone in the team group.
if (!(c.operator && c.operator === s.lark_open_id) && !(c.chat_id && c.chat_id === s.lark_chat_id)) return [];
const p = rowsOf('Clicked post')[0];
const base = { reply_to: c.message_id };
if (!p || !c.token || p.approval_token !== c.token) return [{ json: { ...base, valid: false, text: 'Thẻ này cũ rồi, hong dùng được nữa.' } }];
if (p.status !== 'needs_owner') return [{ json: { ...base, valid: false, text: `Bài #${p.Id} đang ở trạng thái ${p.status}, bấm nữa hong đổi gì.` } }];
if (c.action === 'reject') return [{ json: { ...base, valid: true, row_id: p.Id, status: 'rejected', approved_text: null, scheduled_for: null, slot: null, text: `Đã bỏ bài #${p.Id}.` } }];
if (c.action !== 'approve') return [];
const now = DateTime.now().setZone(TZ);
// A time the owner set through chat stands; otherwise the next free slot.
const own = p.scheduled_for && parseDt(p.scheduled_for) > now ? { at: parseDt(p.scheduled_for), slot: p.slot || 'hẹn riêng' } : null;
const taken = rowsOf('Queue').filter((q) => q.Id !== p.Id && q.scheduled_for).map((q) => q.scheduled_for);
const next = own || nextSlot(s.slots, taken, now.plus({ minutes: 15 }));
if (!next) return [{ json: { ...base, valid: false, text: `Hong tìm được khung giờ trống nào cho bài #${p.Id}: coi lại slots trong cấu hình.` } }];
return [{ json: { ...base, valid: true, row_id: p.Id, status: 'approved', approved_text: p.text, scheduled_for: iso(next.at), slot: next.slot,
  text: `Đã duyệt bài #${p.Id}, lên Facebook lúc ${next.at.setLocale('vi').toFormat('HH:mm cccc dd/MM')}.` } }];

const TZ = 'Asia/Ho_Chi_Minh';
// The NocoDB node nests a row as { id, id_fields, fields }.
const rowsOf = (name) => ($(name).isExecuted ? $(name).all() : [])
  .map((i) => i.json || {})
  .filter((j) => j.id !== undefined && j.id !== null)
  .map((j) => ({ Id: j.id, ...(j.fields || {}) }));
const settingsOf = (name) => Object.fromEntries(
