const parseDt = (s) => DateTime.fromISO(String(s || '').trim().replace(' ', 'T'), { setZone: true }).setZone(TZ);
const iso = (dt) => dt.setZone(TZ).toISO({ suppressMilliseconds: true });

// Image keys in a Lark message: pictures, pictures in rich text, and image files.
const imagesOf = (msg) => {
  try {
    const c = JSON.parse((msg.body && msg.body.content) || '{}');
    if (msg.msg_type === 'image' && c.image_key) return [c.image_key];
    if (msg.msg_type === 'file' && c.file_key && /\.(png|jpe?g|webp)$/i.test(c.file_name || '')) return [c.file_key];
    if (msg.msg_type === 'post') return (Array.isArray(c.content) ? c.content : []).flat().filter((el) => el && el.tag === 'img' && el.image_key).map((el) => el.image_key);
  } catch (e) {}
  return [];
};
// Plain text of a Lark message of any type, for reading and for thread history.
const plainOf = (msg) => {
  const raw = (msg && msg.body && msg.body.content) || '';
  try {
    const c = JSON.parse(raw || '{}');
    if (msg.msg_type === 'text') return c.text || '';
    if (msg.msg_type === 'post') {
      const blocks = Array.isArray(c.content) ? c.content : [];
      return [c.title || '', ...blocks.map((line) => (Array.isArray(line) ? line : []).map((el) => (el.tag === 'img' ? '[ảnh]' : el.text || el.href || '')).join(''))].filter(Boolean).join('\n');
    }
    if (msg.msg_type === 'image' || (msg.msg_type === 'file' && imagesOf(msg).length)) return '[ảnh]';
    return JSON.stringify(c).replace(/"(tag|type|template|schema|behaviors|value|width|flex_mode|img_key|image_key)":"[^"]*",?/g, '').replace(/[{}\[\]"]/g, ' ').replace(/\s+/g, ' ').trim();
  } catch (e) {
    return String(raw).slice(0, 2000);
  }
};

// G0: only what concerns the bot goes further. What it means is the chat agent's call.
const s = settingsOf('Settings');
const r = $json;
if (r.code !== 0) throw new Error(`Lark get message failed: ${r.code} ${r.msg}`);
const m = ((r.data && r.data.items) || [])[0];
if (!m || !m.sender || m.sender.sender_type !== 'user') return [];
const mentions = Array.isArray(m.mentions) ? m.mentions : [];
const botMentioned = mentions.some((x) => x.id === s.lark_bot_open_id);
let text = plainOf(m);
for (const x of mentions) text = text.split(x.key).join(x.id === s.lark_bot_open_id ? '' : `@${x.name}`);
text = text.replace(/\[ảnh\]/g, '').trim();
const images = imagesOf(m);
if (!text && !images.length) return [];
const group = $('Classify').first().json.chat_type === 'group';
const base = { text, images, group, chat_id: m.chat_id, sender: m.sender.id, message_id: m.message_id, parent_id: m.parent_id || '', root_id: m.root_id || '', thread_id: m.thread_id || '', sent_at: DateTime.fromMillis(Number(m.create_time) || Date.now()).setZone(TZ).toISO({ suppressMilliseconds: true }) };
if (!group) return m.sender.id === s.lark_open_id ? [{ json: { ...base, access: 'ok' } }] : [];
if (m.chat_id !== s.lark_chat_id) return [];
if (botMentioned || text.startsWith('/')) return [{ json: { ...base, access: 'ok' } }];
// A reply or a thread message counts only where the bot already spoke; Gate checks.
return m.parent_id || m.root_id || m.thread_id ? [{ json: { ...base, access: 'thread_check' } }] : [];

