const m = $('Read message').first().json;
const s = settingsOf('Settings');
const members = (($('Fetch members').first().json.data || {}).items || []);
const names = Object.fromEntries(members.map((x) => [x.member_id, x.name]));
// Lark lists the bot's own messages with its app id as sender.id, not its open_id.
const fromBot = (x) => Boolean(x && x.sender && x.sender.sender_type === 'app' && x.sender.id === s.lark_app_id);
const nameOf = (x) => (fromBot(x) ? 'bạn (bot)' : names[x && x.sender && x.sender.id] || (x && x.sender && x.sender.id === s.lark_open_id ? 'sếp' : 'một người trong nhóm'));
const found = (($('Fetch thread').first().json.data || {}).items || []).filter((x) => x.message_id !== m.message_id);
if (m.access === 'thread_check' && !found.some(fromBot)) return [];
const thread = found.slice(-30).map((x) => ({ speaker: nameOf(x), text: plainOf(x).slice(0, 1500), is_agent: fromBot(x), sent_at: DateTime.fromMillis(Number(x.create_time) || 0).setZone(TZ).toISO({ suppressMilliseconds: true }) }));
// What the thread is about: the post card ("Bài #N") or an idea the bot named ("ý tưởng #N").
const botText = found.filter(fromBot).map((x) => (x.body && x.body.content) || '').join('\n');
const post = botText.match(/Bài #(\d+)/);
const idea = botText.match(/ý tưởng #(\d+)/);
const who = names[m.sender] || (m.sender === s.lark_open_id ? 'sếp' : 'một người trong nhóm');
// Pictures of this message first, then those of the thread, newest first: 10 at most.
const pictures = [
  ...m.images.map((k) => ({ source: `${m.message_id} ${k}`, from_this_message: true })),
  ...[...found].reverse().flatMap((x) => imagesOf(x).map((k) => ({ source: `${x.message_id} ${k}`, from_this_message: false }))),
].slice(0, 10).map((p, i) => ({ property: `picture_${i + 1}`, ...p }));
return [{ json: { ...m, who, thread, pictures, about: post || idea ? { post_id: post ? Number(post[1]) : null, idea_id: idea ? Number(idea[1]) : null } : null, reply_to: m.message_id } }];

const TZ = 'Asia/Ho_Chi_Minh';
// The NocoDB node nests a row as { id, id_fields, fields }.
const rowsOf = (name) => ($(name).isExecuted ? $(name).all() : [])
  .map((i) => i.json || {})
  .filter((j) => j.id !== undefined && j.id !== null)
  .map((j) => ({ Id: j.id, ...(j.fields || {}) }));
const settingsOf = (name) => Object.fromEntries(
  rowsOf(name).filter((r) => r.key).map((r) => [r.key, (r.value ?? '').toString().trim()]));
const linesOf = (v) => String(v || '').split('\n').map((s) => s.trim()).filter(Boolean);
// NocoDB returns DateTime in UTC as "2026-09-17 13:00:00+00:00".
const parseDt = (s) => DateTime.fromISO(String(s || '').trim().replace(' ', 'T'), { setZone: true }).setZone(TZ);
const iso = (dt) => dt.setZone(TZ).toISO({ suppressMilliseconds: true });

const g = $('Gate').first().json;
const s = settingsOf('Settings');
// The agent passes every image binary of its input item to the model: picture_1, picture_2, ...
const binary = {};
const missing = [];
if ($('Download picture').isExecuted) {
  $('Download picture').all().forEach((item, i) => {
    const b = item.binary && item.binary.data;
    if (b && String(b.mimeType || '').startsWith('image/')) binary[`picture_${i + 1}`] = b;
    else missing.push(`picture_${i + 1}`);
  });
}
const task = {
  message: { message_id: g.message_id, chat_id: g.chat_id, thread_id: g.thread_id || null, sender_name: g.who, sender_is_owner: g.sender === s.lark_open_id, text: g.text, sent_at: g.sent_at },
  thread: g.thread,
  pictures: g.pictures.filter((p) => !missing.includes(p.property)),
  about: g.about,
  settings: { slots: linesOf(s.slots), daily_quota: Number(s.daily_quota) || 0, topics: linesOf(s.topics), avoid: linesOf(s.avoid), rules: linesOf(s.rules) },
  now: iso(DateTime.now()),
};
const note = missing.length ? `\n\n(${missing.join(', ')} tải hong được nên bạn hong thấy.)` : '';
return [{ json: { task: JSON.stringify(task, null, 1) + note, reply_to: g.message_id }, binary }];

const out = String($json.output || '').trim();
// NO_REPLY: a thread message meant for someone else.
return out && out !== 'NO_REPLY' ? [{ json: { text: out.slice(0, 15000) } }] : [];
